/**
 *
 * DataTableColumnToggle provides a UI for toggling column visibility in DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableColumnToggle
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableColumnTogglePassThroughType<E> = PassThroughType<DataTableColumnToggleInstance, E>;
export interface DataTableColumnTogglePassThrough {
    root?: DataTableColumnTogglePassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
export interface DataTableColumnToggleColumn {
    field: string;
    header: string;
}
export interface DataTableColumnToggleProps extends BaseComponentProps<DataTableColumnToggleInstance, unknown, DataTableColumnTogglePassThrough, 'div'> {
    /**
     * Available columns that can be toggled.
     */
    columns: DataTableColumnToggleColumn[];
    /**
     * Currently visible column fields.
     */
    visibleFields?: string[];
    /**
     * Default visible column fields for uncontrolled mode.
     */
    defaultVisibleFields?: string[];
    /**
     * Callback when column visibility changes.
     */
    onVisibleFieldsChange?: (event: {
        originalEvent: React.SyntheticEvent;
        visibleFields: string[];
    }) => void;
}
export interface DataTableColumnToggleState {
}
/**
 * Slot context exposed to the `children` render prop and on the component instance.
 */
export interface DataTableColumnToggleExposes {
    datatable: DataTableRootInstance | undefined | null;
    /** Columns eligible for toggling (echo of the `columns` prop). */
    columns: DataTableColumnToggleColumn[];
    /** Currently visible column fields. */
    visibleFields: string[];
    /** Whether the given field is currently visible. */
    isVisible: (field: string) => boolean;
    /** Toggle visibility for a single field. */
    toggle: (event: React.SyntheticEvent, field: string) => void;
    /** Show every column. */
    showAll: (event: React.SyntheticEvent) => void;
    /** Hide every column. */
    hideAll: (event: React.SyntheticEvent) => void;
}
export type DataTableColumnToggleInstance = ComponentInstance<DataTableColumnToggleProps, DataTableColumnToggleState, DataTableColumnToggleExposes>;
